import {clamp,dist,seeded,angleDelta} from './premium-utils.js';
export const ROBOT_TYPES=[{name:'Sweepy',kind:'cleaner',test:'Follow the cleaning route',color:'#7dddc7'},{name:'Disco Dot',kind:'dancer',test:'Repeat the dance beat',color:'#cba6fb'},{name:'Chef Sprocket',kind:'cook',test:'Serve the test plates in order',color:'#ffca8d'},{name:'Skipper',kind:'drone',test:'Balance the flight stabilizers',color:'#96cfff'},{name:'Parcel Pal',kind:'delivery',test:'Check the wheel route',color:'#f4b5ba'},{name:'Melody',kind:'musician',test:'Play the diagnostic notes',color:'#b9acee'},{name:'Tiny Titan',kind:'toy',test:'Run the toy obstacle test',color:'#f2d97e'},{name:'Rivet',kind:'industrial',test:'Calibrate the mechanical arm',color:'#9dc3ce'},{name:'Professor Bloop',kind:'experiment',test:'Stabilize the experimental reactor',color:'#d0eaa0'}];
export const REPAIR_TOOLS=[['scan','Scanner'],['screw','Screwdriver'],['wrench','Wrench'],['wire','Wire tool'],['gear','Gear tool'],['solder','Soldering pen'],['brush','Cleaning brush'],['battery','Battery tool'],['assembly','Assembly tool']].map(([id,name])=>({id,name}));
export const FAULTS=['wheel','motor','screw','gear','battery','wire','arm','sensor','circuit','dirty'];
export class RobotModel{
 constructor({level=1,difficulty=3,mode='career',seed=42}={}){this.kind='robot';this.levelId=level;this.difficulty=difficulty;this.mode=mode;this.seed=seed;this.rng=seeded(seed+level*611);this.robot={...ROBOT_TYPES[(level-1)%9]};this.phase='play';this.tool='scan';this.clock=0;this.duration=mode==='sandbox'?Infinity:300000;this.done=false;this.complete=false;this.hits=0;this.mistakes=0;this.events=[];this.pointers=new Map();this.panelOpen=false;this.testStage=0;this.testing=false;this.batteryType=0;this.correctBattery=(level+difficulty)%3;this.screws=[{x:290,y:200},{x:770,y:200},{x:290,y:505},{x:770,y:505}].map(p=>({...p,turn:1}));const n=mode==='quick'?2:mode==='assembly'?6:Math.min(7,1+difficulty+Math.floor(level/10)),pool=mode==='assembly'?['wheel','motor','gear','battery','arm','sensor']:FAULTS;this.parts=Array.from({length:n},(_,i)=>{const shuffled=[...pool];for(let n=shuffled.length-1;n>0;n--){const j=Math.floor(this.rng()*(n+1));[shuffled[n],shuffled[j]]=[shuffled[j],shuffled[n]];}const type=shuffled[(level-1+i)%shuffled.length];return{id:i,type,x:375+(i%3)*155,y:275+Math.floor(i/3)*88,scanned:false,fixed:false,progress:0,disconnected:mode==='assembly',removed:mode==='assembly'&&['wheel','motor','arm','sensor'].includes(type),placed:false,angle:(i%3+1)*Math.PI/4,path:0};});this.feedback='SCAN each flashing component. Open the panel by turning all four screws counterclockwise.';this.lastError=-1000;this.testingPoints=[{x:350,y:550},{x:500,y:550},{x:650,y:550}];}
 error(text){this.feedback=text;if(this.clock-this.lastError>450){this.mistakes++;this.lastError=this.clock;this.events.push('bad');}}
 finishPart(p){if(p.fixed)return;p.fixed=true;this.hits++;this.events.push('repair');this.feedback='Restored '+p.type+'. '+this.parts.filter(p=>p.fixed).length+'/'+this.parts.length+' repairs done. Close the panel, tighten screws, then TEST.';}
 action(id){if(id==='panel'){if(!this.panelOpen){if(this.screws.some(s=>s.turn>.02)){this.error('Loosen all four panel screws first.');return false;}this.panelOpen=true;this.feedback='Panel open. Scan a fault and use its indicated repair tool.';return true;}if(this.parts.some(p=>!p.fixed)){this.error('Repair all marked components before closing the panel.');return false;}this.panelOpen=false;this.feedback='Panel closed. Turn the four screws clockwise to secure it.';return true;}if(id==='batteryType'){this.batteryType=(this.batteryType+1)%3;this.feedback='Battery type '+['A · 6V','B · 12V','C · 24V'][this.batteryType]+'. Match the socket label.';return true;}if(id==='test'){if(this.mode==='diagnosis'&&this.parts.every(p=>p.scanned)){this.complete=this.done=true;this.hits=this.parts.length;return true;}if(this.parts.some(p=>!p.fixed)||this.panelOpen||this.screws.some(s=>s.turn<.98)){this.error('Test failed: repair every fault, close the panel and tighten all screws.');return false;}this.testing=true;this.testStage=0;this.feedback=this.robot.test+': tap illuminated controls 1 → 2 → 3.';return true;}return false;}
 input(kind,x,y,id){if(this.done)return false;if(kind==='down'){if(this.testing){const hit=this.testingPoints.findIndex(p=>dist(p,{x,y})<45);if(hit===this.testStage){this.testStage++;this.events.push('test');if(this.testStage===3){this.complete=this.done=true;this.events.push('finish');}}else this.error('Test sequence paused. Follow the illuminated control.');return true;}const screw=this.screws.find(s=>dist(s,{x,y})<32),part=this.parts.find(p=>dist(p,{x,y})<50);if(this.tool==='scan'&&part){part.scanned=true;this.events.push('scan');const guides={wheel:'WRENCH to loosen → ASSEMBLY tray to replace.',motor:'WIRE to disconnect → WRENCH to loosen → ASSEMBLY replace → WIRE reconnect.',screw:'SCREWDRIVER clockwise to tighten loose component screw.',gear:'GEAR tray to socket, then rotate its notch upward.',battery:'Choose matching voltage, then BATTERY tray to socket. Needs '+['A · 6V','B · 12V','C · 24V'][this.correctBattery],wire:'WIRE: connect the cyan terminal to its gold partner.',arm:'WRENCH to release → ASSEMBLY tray to reconnect.',sensor:'ASSEMBLY tray to sensor socket.',circuit:'SOLDER: trace the illuminated zigzag from left to right.',dirty:'BRUSH: scrub the dirty component back and forth.'};this.feedback=part.type.toUpperCase()+': '+guides[part.type];return true;}if(this.tool==='scan'){this.error('Aim the scanner at a flashing component.');return false;}const p={id,tool:this.tool,start:{x,y},prev:{x,y},x,y,part:part?.id,screw:screw?this.screws.indexOf(screw):null,angle:part?Math.atan2(y-part.y,x-part.x):screw?Math.atan2(y-screw.y,x-screw.x):0,turn:0,travel:0,trace:0,fromTray:y>535&&x<270};if(this.panelOpen&&this.tool==='wire'&&part&&part.scanned&&part.type==='motor'&&!part.disconnected){part.disconnected=true;this.feedback='Motor wire disconnected. Use the wrench, then fit the replacement.';return true;}this.pointers.set(id,p);return true;}
 const p=this.pointers.get(id);if(!p)return false;if(kind==='move'){const old={x:p.x,y:p.y};p.prev=old;p.x=x;p.y=y;p.travel+=dist(old,p);this.apply(p);return true;}this.pointers.delete(id);if(kind==='cancel')return true;p.x=x;p.y=y;this.finishGesture(p);return true;}
 apply(p){const screw=p.screw!==null?this.screws[p.screw]:null;if(p.tool==='screw'&&screw&&!this.panelOpen){const a=Math.atan2(p.y-screw.y,p.x-screw.x),delta=angleDelta(a,p.angle);p.angle=a;screw.turn=clamp(screw.turn+delta/(Math.PI*2),0,1);this.feedback=(screw.turn<.02?'Screw released.':'Screw '+Math.round(screw.turn*100)+'% secure.');return;}const part=this.parts[p.part];if(!part||!part.scanned||part.fixed)return;if(!this.panelOpen){this.feedback='Open the panel before treating components.';return;}const d=dist(p,part);if(p.tool==='screw'&&part.type==='screw'&&d<45){const a=Math.atan2(p.y-part.y,p.x-part.x),delta=angleDelta(a,p.angle);p.angle=a;part.progress+=Math.max(0,delta)/(Math.PI*2);if(part.progress>=1)this.finishPart(part);}
 if(p.tool==='wrench'&&['wheel','motor','arm'].includes(part.type)&&d<55){if(part.type==='motor'&&!part.disconnected){this.feedback='Disconnect the motor wire before loosening it.';return;}const a=Math.atan2(p.y-part.y,p.x-part.x);p.turn+=Math.abs(angleDelta(a,p.angle));p.angle=a;if(p.turn>Math.PI*1.5){part.removed=true;this.feedback='Component released. Drag a fresh part from the ASSEMBLY tray.';}}
 if(p.tool==='brush'&&part.type==='dirty'&&d<47){part.progress+=dist(p,p.prev)/[180,220,260,300,340][this.difficulty-1];if(part.progress>=1)this.finishPart(part);}
 if(p.tool==='gear'&&part.type==='gear'&&part.placed&&d<60){const a=Math.atan2(p.y-part.y,p.x-part.x);part.angle+=angleDelta(a,p.angle);p.angle=a;this.feedback='Align the gear notch to the upward gold mark.';}
 if(p.tool==='solder'&&part.type==='circuit'){const path=this.circuitPath(part),target=path[part.path];if(target&&dist(p,target)<[23,21,18,15,13][this.difficulty-1]){part.path++;part.progress=part.path/path.length;if(part.path===path.length)this.finishPart(part);}else if(d>70)this.feedback='Keep the soldering pen on the highlighted circuit path.';}
 }
 circuitPath(p){return Array.from({length:7},(_,i)=>({x:p.x-45+i*15,y:p.y+(i%2?12:-12)}));}
 finishGesture(p){if(!this.panelOpen)return;const part=this.parts.find(q=>dist(q,p)<48);if(!part||!part.scanned||part.fixed)return;if(p.tool==='wire'&&['wire','motor'].includes(part.type)){if(part.type==='motor'&&!part.placed){this.feedback='Replace the motor before reconnecting it.';return;}const start={x:part.x-28,y:part.y+15},end={x:part.x+28,y:part.y+15};if(dist(p.start,start)<25&&dist(p,end)<25)this.finishPart(part);else this.error('Connect the cyan terminal to the gold terminal on this component.');}
 if(p.tool==='assembly'&&p.fromTray&&['wheel','motor','arm','sensor'].includes(part.type)){if(part.type!=='sensor'&&!part.removed){this.error('Loosen and remove this part with the wrench first.');return;}part.placed=true;if(part.type==='motor')this.feedback='New motor fitted. Reconnect its cyan and gold terminals.';else this.finishPart(part);}
 if(p.tool==='battery'&&part.type==='battery'&&p.fromTray){if(this.batteryType===this.correctBattery)this.finishPart(part);else this.error('Voltage mismatch. The socket label shows '+['A · 6V','B · 12V','C · 24V'][this.correctBattery]+'.');}
 if(p.tool==='gear'&&part.type==='gear'){if(p.fromTray){part.placed=true;this.feedback='Gear seated. Rotate around it until the notch points up.';}else if(part.placed&&Math.abs(angleDelta(part.angle,0))<.3)this.finishPart(part);}
 }
 update(dt){if(this.done)return;this.clock+=dt;if(this.clock>=this.duration){this.done=true;this.feedback='Workshop timer ended. Restart for unlimited new attempts.';}}cancel(){this.pointers.clear();}dispose(){this.cancel();}get score(){return Math.max(0,this.hits*180+this.parts.filter(p=>p.scanned).length*25+(this.complete?800+Math.max(0,Math.floor((300000-this.clock)/500)):0)-this.mistakes*45);}summary(){return{completed:this.complete,robot:this.robot.name,repairs:this.parts.filter(p=>p.fixed).length,faults:this.parts.length,mistakes:this.mistakes,testPassed:this.complete&&this.testing&&this.testStage===3,diagnosisPassed:this.complete&&this.mode==='diagnosis',diagnosed:this.parts.filter(p=>p.scanned).length};}
}
